 "content": "def transform(grid):
    out = [row[:] for row in grid]
    zero_cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 0]
    if not zero_cells:
        return out
    # The 2x2 zero marker selects its two rows and two columns; retain the
    # marked color (2) while erasing other cells on those selected lines.
    rows = {r for r, _ in zero_cells}
    cols = {c for _, c in zero_cells}
    for r in range(len(out)):
        for c in range(len(out[r])):
            if (r in rows or c in cols) and out[r][c] != 2:
                out[r][c] = 0
    return out
